"    privateFileTag: \" · Private (Burn on download)\",\n"
"    placeholderBroadcast: \"Type text here to broadcast to all devices (auto-destruct)...\",\n"
"    placeholderPrivate: \"Private message for [{name}], wiped immediately once read...\",\n"
"    toastCopied: \"Copied: \",\n"
"    toastBurned: \"Permanently wiped from all devices & host!\",\n"
"    toastSent: \"Message sent!\",\n"
"    toastSendFailed: \"Failed to send\",\n"
"    toastClipFetched: \"PC clipboard synced\",\n"
"    toastClipEmpty: \"Clipboard is empty or inaccessible\",\n"
"    toastUploadSuccess: \"File uploaded successfully!\",\n"
"    toastUploadFailed: \"Upload failed\",\n"
"    toastQrSwitched: \"QR code switched to: \",\n"
"    toastNameUpdated: \"Nickname updated to: \",\n"
"    toastInputEmpty: \"Please enter text\",\n"
"    promptEditName: \"Enter your display nickname on this network:\",\n"
"    devUnknown: \"Device\",\n"
"    langBtnText: \"🌐 简体中文\"\n"
"  }\n"
"};\n"
"\n"
"let currentLang = sessionStorage.getItem('qm_lang') || 'zh';\n"
"function t(key) {\n"
"  return (I18N[currentLang] && I18N[currentLang][key]) || (I18N.zh[key]) || key;\n"
"}\n"
"\n"
"function applyLanguage(lang) {\n"
"  currentLang = lang;\n"
"  sessionStorage.setItem('qm_lang', lang);\n"
"  document.documentElement.lang = (lang === 'zh' ? 'zh-CN' : 'en');\n"
"  \n"
"  // 更新所有声明 data-i18n 的元素\n"
"  document.querySelectorAll('[data-i18n]').forEach(el => {\n"
"    const key = el.getAttribute('data-i18n');\n"
"    if (t(key)) el.innerHTML = t(key);\n"
"  });\n"
"  \n"
"  // 语言切换按钮文字\n"
"  document.getElementById('langToggleBtn').innerText = t('langBtnText');\n"
"  \n"
"  // 更新在线状态文本\n"
"  if (lastUsersCount >= 0) {\n"
"    document.getElementById('onlineCountText').innerText = lastUsersCount + t('onlineDevices');\n"
"  } else {\n"
"    document.getElementById('onlineCountText').innerText = t('connecting');\n"
"  }\n"
"  \n"
"  // 重新渲染相关列表与提示\n"
"  updatePlaceholder();\n"
"  if (lastCachedUsers.length > 0) updateUsersList(lastCachedUsers);\n"
"  if (lastCachedAddresses.length > 0) renderAddresses(lastCachedAddresses);\n"
"}\n"
"\n"
"function toggleLang() {\n"
"  applyLanguage(currentLang === 'zh' ? 'en' : 'zh');\n"
"}\n"
"\n"
"// ---------------- 客户端身份与会话 ----------------\n"
"let myClientId = sessionStorage.getItem('qm_client_id');\n"
"if (!myClientId) {\n"
"  myClientId = 'c_' + Math.random().toString(36).substr(2, 9);\n"
"  sessionStorage.setItem('qm_client_id', myClientId);\n"
"}\n"
"\n"
"let myClientName = sessionStorage.getItem('qm_client_name');\n"
"if (!myClientName) {\n"
"  const ua = navigator.userAgent;\n"
"  let dev = t('devUnknown');\n"
"  if (/iPhone/i.test(ua)) dev = 'iPhone';\n"
"  else if (/iPad/i.test(ua)) dev = 'iPad';\n"
"  else if (/Macintosh/i.test(ua)) dev = 'MacBook';\n"
"  else if (/Windows/i.test(ua)) dev = 'Windows PC';\n"
"  else if (/Android/i.test(ua)) dev = 'Android';\n"
"  myClientName = dev + '-' + myClientId.substr(-4);\n"
"  sessionStorage.setItem('qm_client_name', myClientName);\n"
"}\n"
"document.getElementById('myDisplayName').innerText = myClientName + ' ✏️';\n"
"\n"
"function changeMyName() {\n"
"  const newName = prompt(t('promptEditName'), myClientName);\n"
"  if (newName && newName.trim()) {\n"
"    myClientName = newName.trim();\n"
"    sessionStorage.setItem('qm_client_name', myClientName);\n"
"    document.getElementById('myDisplayName').innerText = myClientName + ' ✏️';\n"
"    showToast(t('toastNameUpdated') + myClientName);\n"
"    fetchSync();\n"
"  }\n"
"}\n"
"\n"
"const isMobile = /iPhone|iPad|iPod|Android/i.test(navigator.userAgent);\n"
"if (isMobile) {\n"
"  document.getElementById('toggleQrBtn').style.display = 'inline-block';\n"
"  document.getElementById('netDashboard').style.display = 'none';\n"
"}\n"
"function toggleQr() {\n"
"  const nd = document.getElementById('netDashboard');\n"
"  nd.style.display = (nd.style.display === 'none') ? 'grid' : 'none';\n"
"}\n"
"\n"
"function showToast(msg) {\n"
"  const toast = document.getElementById('toast');\n"
"  toast.innerText = msg;\n"
"  toast.style.display = 'block';\n"
"  setTimeout(() => { toast.style.display = 'none'; }, 2000);\n"
"}\n"
"\n"
"function copyText(txt) {\n"
"  if (navigator.clipboard && navigator.clipboard.writeText) {\n"
"    navigator.clipboard.writeText(txt).then(() => showToast(t('toastCopied') + txt));\n"
"  } else {\n"
"    const ta = document.createElement('textarea');\n"
"    ta.value = txt;\n"
"    document.body.appendChild(ta);\n"
"    ta.select();\n"
"    document.execCommand('copy');\n"
"    document.body.removeChild(ta);\n"
"    showToast(t('toastCopied') + txt);\n"
"  }\n"
"}\n"
"\n"
"function updatePlaceholder() {\n"
"  const sel = document.getElementById('textTargetSelect');\n"
"  const ta = document.getElementById('textInput');\n"
"  if (!sel || !ta) return;\n"
"  if (sel.value === 'all') {\n"
"    ta.placeholder = t('placeholderBroadcast');\n"
"  } else {\n"
"    const targetText = sel.options[sel.selectedIndex] ? sel.options[sel.selectedIndex].text : '';\n"
"    ta.placeholder = t('placeholderPrivate').replace('{name}', targetText);\n"
"  }\n"
"}\n"
"\n"
"let lastUsersCount = -1;\n"
"let lastCachedUsers = [];\n"
"function updateUsersList(users) {\n"
"  if (!users) return;\n"
"  lastCachedUsers = users;\n"
"  lastUsersCount = users.length;\n"
"  document.getElementById('onlineCountText').innerText = users.length + t('onlineDevices');\n"
"\n"
"  // 渲染 Chips\n"
"  const chipsContainer = document.getElementById('userChipsList');\n"
"  chipsContainer.innerHTML = '';\n"
"  users.forEach(u => {\n"
"    const isMe = (u.client_id === myClientId);\n"
"    const chip = document.createElement('div');\n"
"    chip.className = 'chip' + (u.is_host ? ' host' : '');\n"
"    chip.innerHTML = `\n"
"      <span>${u.is_host ? '🖥️' : '📱'}</span>\n"
"      <span><strong>${u.name}</strong>${isMe ? t('tagMe') : ''}</span>\n"
"      <span style=\"font-size:11px;color:#8e8e93;\">${u.ip}</span>\n"
"    `;\n"
"    chipsContainer.appendChild(chip);\n"
"  });\n"
"\n"
"  // 刷新 Target Selects (保持当前选中)\n"
"  ['textTargetSelect', 'fileTargetSelect'].forEach(id => {\n"
"    const sel = document.getElementById(id);\n"
"    const curVal = sel.value;\n"
"    const isText = (id === 'textTargetSelect');\n"
"    sel.innerHTML = `<option value=\"all\">${isText ? t('everyoneText') : t('everyoneFile')}</option>`;\n"
"    users.forEach(u => {\n"
"      if (u.client_id !== myClientId) {\n"
"        const opt = document.createElement('option');\n"
"        opt.value = u.client_id;\n"
"        opt.innerText = (u.is_host ? t('pcHostPrefix') : t('mobilePrefix')) + u.name + ' (' + u.ip + ')';\n"
"        sel.appendChild(opt);\n"
"      }\n"
"    });\n"
"    sel.value = curVal || 'all';\n"
"  });\n"
"}\n"
"\n"
"function selectUrl(url) {\n"
"  document.getElementById('qrImage').src = '/api/qrcode?url=' + encodeURIComponent(url) + '&t=' + Date.now();\n"
"  document.querySelectorAll('.addr-item').forEach(el => {\n"
"    if (el.dataset.url === url) el.classList.add('active');\n"
"    else el.classList.remove('active');\n"
"  });\n"
"  showToast(t('toastQrSwitched') + url);\n"
"}\n"
"\n"
"let lastCachedAddresses = [];\n"
"function renderAddresses(list) {\n"
"  const container = document.getElementById('addrList');\n"
"  if (!list || list.length === 0) return;\n"
"  lastCachedAddresses = list;\n"
"  let html = '';\n"
"  list.forEach((item, idx) => {\n"
"    const isRec = (idx === 0);\n"
"    // 标签多语言转换\n"
"    let label = item.label;\n"
"    if (currentLang === 'en') {\n"
"      if (label.indexOf('Wi-Fi') !== -1 || label.indexOf('局域网') !== -1) label = 'Wi-Fi / LAN';\n"
"      else if (label.indexOf('备用') !== -1) label = 'Alternate Interface';\n"
"      else if (label.indexOf('本机') !== -1) label = 'Loopback';\n"
"    }\n"
"    html += `\n"
"      <div class=\"addr-item ${isRec ? 'active' : ''}\" data-url=\"${item.url}\" onclick=\"selectUrl('${item.url}')\">\n"
"        <div class=\"addr-left\">\n"
"          <div class=\"addr-label\">\n"
"            <span>${label}</span>\n"
"            ${isRec ? `<span class=\"badge-rec\">${t('badgeRec')}</span>` : ''}\n"
"          </div>\n"
"          <div class=\"addr-url\">${item.url}</div>\n"
"        </div>\n"
"        <button class=\"btn-copy-addr\" onclick=\"event.stopPropagation(); copyText('${item.url}')\">${t('copyBtn')}</button>\n"
"      </div>\n"
"    `;\n"
"  });\n"
"  container.innerHTML = html;\n"
"}\n"
"\n"
"function clearInput() {\n"
"  document.getElementById('textInput').value = '';\n"
"}\n"
"\n"
"function sendText() {\n"
"  const input = document.getElementById('textInput');\n"
"  const val = input.value.trim();\n"
"  if (!val) { showToast(t('toastInputEmpty')); return; }\n"
"  const target = document.getElementById('textTargetSelect').value;\n"
"\n"
"  const xhr = new XMLHttpRequest();\n"
"  xhr.open('POST', '/api/text?from_id=' + encodeURIComponent(myClientId) +\n"
"                    '&from_name=' + encodeURIComponent(myClientName) +\n"
"                    '&target_id=' + encodeURIComponent(target), true);\n"
"  xhr.setRequestHeader('Content-Type', 'text/plain; charset=utf-8');\n"
"  xhr.onload = function() {\n"
"    if (xhr.status === 200) {\n"
"      showToast(t('toastSent'));\n"
"      input.value = '';\n"
"      fetchSync();\n"
"    } else {\n"
"      showToast(t('toastSendFailed'));\n"
"    }\n"
"  };\n"
"  xhr.send(val);\n"
"}\n"
"\n"
"function burnItem(type, id) {\n"
"  const xhr = new XMLHttpRequest();\n"
"  xhr.open('POST', '/api/burn?type=' + type + '&id=' + id, true);\n"
"  xhr.onload = function() {\n"
"    showToast(t('toastBurned'));\n"
"    fetchSync();\n"
"  };\n"
"  xhr.send();\n"
"}\n"
"\n"
"function syncClipboard() {\n"
"  const xhr = new XMLHttpRequest();\n"
"  xhr.open('GET', '/api/clipboard', true);\n"
"  xhr.onload = function() {\n"
"    if (xhr.status === 200 && xhr.responseText) {\n"
"      document.getElementById('textInput').value = xhr.responseText;\n"
"      showToast(t('toastClipFetched'));\n"
"    } else {\n"
"      showToast(t('toastClipEmpty'));\n"
"    }\n"
"  };\n"
"  xhr.send();\n"
"}\n"
"\n"
"function uploadFile(file) {\n"
"  if (!file) return;\n"
"  const target = document.getElementById('fileTargetSelect').value;\n"
"  const bar = document.getElementById('progressBar');\n"
"  const inner = document.getElementById('progressInner');\n"
"  bar.style.display = 'block';\n"
"  inner.style.width = '0%';\n"
"  const xhr = new XMLHttpRequest();\n"
"  xhr.open('POST', '/api/upload?name=' + encodeURIComponent(file.name) +\n"
"                    '&from_id=' + encodeURIComponent(myClientId) +\n"
"                    '&from_name=' + encodeURIComponent(myClientName) +\n"
"                    '&target_id=' + encodeURIComponent(target), true);\n"
"  xhr.upload.onprogress = function(e) {\n"
"    if (e.lengthComputable) {\n"
"      inner.style.width = Math.round((e.loaded / e.total) * 100) + '%';\n"
"    }\n"
"  };\n"
"  xhr.onload = function() {\n"
"    bar.style.display = 'none';\n"
"    if (xhr.status === 200) {\n"
"      showToast(t('toastUploadSuccess'));\n"
"      document.getElementById('fileInput').value = '';\n"
"      fetchSync();\n"
"    } else {\n"
"      showToast(t('toastUploadFailed'));\n"
"    }\n"
"  };\n"
"  xhr.send(file);\n"
"}\n"
"\n"
"function renderMessages(messages) {\n"
"  const list = document.getElementById('msgList');\n"
"  list.innerHTML = '';\n"
"  messages.forEach(m => {\n"
"    const isPrivate = (m.target_id && m.target_id !== 'all');\n"
"    const isFromMe = (m.from_id === myClientId);\n"
"    const item = document.createElement('div');\n"
"    item.className = 'msg-item' + (isPrivate ? ' private' : '');\n"
"    item.innerHTML = `\n"
"      <div class=\"msg-header\">\n"
"        <span>\n"
"          <strong>${m.from_name}</strong>${isFromMe ? t('tagMe') : ''}\n"
"          ${isPrivate ? `<span style=\"color:#ff9500;font-weight:600;\">${t('privateMsgTag')}</span>` : t('broadcastMsgTag')}\n"
"        </span>\n"
"        <span>${m.time || ''}</span>\n"
"      </div>\n"
"      <div class=\"msg-content\"></div>\n"
"      <div class=\"msg-actions\">\n"
"        <button class=\"btn-tiny copy-btn\">${t('copyBtn')}</button>\n"
"        <button class=\"btn-burn burn-btn\">${t('burnBtn')}</button>\n"
"      </div>\n"
"    `;\n"
"    item.querySelector('.msg-content').innerText = m.text;\n"
"    item.querySelector('.copy-btn').onclick = () => copyText(m.text);\n"
"    item.querySelector('.burn-btn').onclick = () => burnItem('msg', m.msg_id);\n"
"    list.appendChild(item);\n"
"  });\n"
"}\n"
"\n"
"function renderFiles(files) {\n"
"  const list = document.getElementById('fileList');\n"
"  list.innerHTML = '';\n"
"  if (!files || files.length === 0) return;\n"
"  files.forEach(f => {\n"
"    const isPrivate = (f.target_id && f.target_id !== 'all');\n"
"    const item = document.createElement('div');\n"
"    item.className = 'file-item' + (isPrivate ? ' private' : '');\n"
"    item.innerHTML = `\n"
"      <div class=\"file-info\">\n"
"        <span class=\"file-name\">${f.name}</span>\n"
"        <span class=\"file-meta\">\n"
"          ${f.size} · ${t('fromPrefix')}${f.from_name}\n"
"          ${isPrivate ? `<strong style=\"color:#ff9500;\">${t('privateFileTag')}</strong>` : ''}\n"
"        </span>\n"
"      </div>\n"
"      <div class=\"file-actions\">\n"
"        <a href=\"/api/download?id=${f.file_id}&client_id=${encodeURIComponent(myClientId)}\" download class=\"btn-tiny\" style=\"text-decoration:none;\">${t('downloadBtn')}</a>\n"
"        <button class=\"btn-burn\" onclick=\"burnItem('file', ${f.file_id})\">${t('burnSmallBtn')}</button>\n"
"      </div>\n"
"    `;\n"
"    list.appendChild(item);\n"
"  });\n"
"}\n"
"\n"
"let isFirst = true;\n"
"function fetchSync() {\n"
"  const xhr = new XMLHttpRequest();\n"
"  xhr.open('GET', '/api/sync?client_id=' + encodeURIComponent(myClientId) +\n"
"                   '&name=' + encodeURIComponent(myClientName), true);\n"
"  xhr.onload = function() {\n"
"    if (xhr.status === 200) {\n"
"      try {\n"
"        const data = JSON.parse(xhr.responseText);\n"
"        if (isFirst && data.interfaces) {\n"
"          renderAddresses(data.interfaces);\n"
"          isFirst = false;\n"
"        }\n"
"        updateUsersList(data.users || []);\n"
"        renderMessages(data.messages || []);\n"
"        renderFiles(data.files || []);\n"
"      } catch(e) {}\n"
"    }\n"
"  };\n"
"  xhr.send();\n"
"}\n"
"\n"
"const dz = document.getElementById('dropZone');\n"
"['dragenter', 'dragover'].forEach(n => dz.addEventListener(n, e => { e.preventDefault(); dz.classList.add('dragover'); }));\n"
"['dragleave', 'drop'].forEach(n => dz.addEventListener(n, e => { e.preventDefault(); dz.classList.remove('dragover'); }));\n"
"dz.addEventListener('drop', e => {\n"
"  if (e.dataTransfer && e.dataTransfer.files.length > 0) {\n"
"    uploadFile(e.dataTransfer.files[0]);\n"
"  }\n"
"});\n"
"\n"
"// 初始化语言\n"
"applyLanguage(currentLang);\n"
"fetchSync();\n"
"setInterval(fetchSync, 1500);\n"
"</script>\n"
"</body>\n"
"</html>\n"
;

#endif // WEB_UI_H
